//! The PTX this crate runs, embedded at compile time.
//!
//! The kernels are written in Y (`tests/bn254_*.ysu`, generated by
//! `tools/gen_bn254_kernels.py`) and compiled by the Y compiler. Embedding the
//! *output* rather than invoking the compiler at runtime is a deliberate
//! product decision: a library that shells out to a sibling binary and reads
//! `.ptx` off disk has a runtime dependency on the build tree, races on the
//! output path when used from several threads, and fails in the field for
//! reasons that have nothing to do with the caller.
//!
//! The cost of embedding is that these files can go stale against the `.ysu`
//! they came from. `tests/ptx_is_not_stale.rs` recompiles each kernel and
//! compares, so that cannot happen silently.

use y::cuda_runtime::{CudaContext, KernelModule};

use crate::error::{Error, Result};

pub const MSM_BUCKET: &str = include_str!("../ptx/bn254_msm_bucket.ptx");
pub const NTT_STAGE: &str = include_str!("../ptx/bn254_ntt_stage.ptx");
pub const PERMUTE: &str = include_str!("../ptx/bn254_permute.ptx");
pub const FR_MUL: &str = include_str!("../ptx/bn254_fr_mul_fast.ptx");
pub const SUB_VEC: &str = include_str!("../ptx/bn254_sub_vec.ptx");

/// Every kernel, as (entry name, PTX). Used by the staleness test.
pub const ALL: &[(&str, &str)] = &[
    ("bn254_msm_bucket", MSM_BUCKET),
    ("bn254_ntt_stage", NTT_STAGE),
    ("bn254_permute", PERMUTE),
    ("bn254_fr_mul_fast", FR_MUL),
    ("bn254_sub_vec", SUB_VEC),
];

pub(crate) fn load(ctx: &CudaContext, entry: &'static str, ptx: &str) -> Result<KernelModule> {
    // A float instruction in a field kernel means some path is lowering limbs
    // through the f32 datapath, which assembles and launches and is silently
    // wrong above 2^24. Cheap to check once at load.
    if ptx.contains("ld.global.f32") || ptx.contains("add.f32") {
        return Err(Error::KernelLoad {
            kernel: entry,
            detail: "PTX routes field limbs through the float datapath".into(),
        });
    }
    ctx.load_ptx(ptx, entry).map_err(|e| Error::KernelLoad {
        kernel: entry,
        detail: e.to_string(),
    })
}
